using System.Net;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.EntityFrameworkCore;
using SnG.Control.Application.Features.Engineering;
using SnG.Control.Application.Features.Measurements;
using SnG.Control.Domain.Entities.Incremental;
using SnG.Control.Domain.Enums;
using SnG.Control.Tests.TestDoubles;
namespace SnG.Control.Tests.Persistence;

public sealed class IncrementalEndToEndTests
{
    [VerificationPostgresFact]
    public async Task TenStructuresTwoTranchesTwoActasPartialResponsesAndRevisionsOverHttp()
    {
        await using var h = await IncrementalHttpHarness.Start();
        Task<MeasurementState> Measurements() => h.Get<MeasurementState>("installer", "Installation", h.Path("measurements"));
        Task<EngineeringState> Engineering() => h.Get<EngineeringState>("engineer", "Engineering", h.Path("engineering"));
        Task<CommercialOpeningState> Commercial() => h.Get<CommercialOpeningState>("advisor", "CommercialAdvisor", h.Path("incremental-opening-records"));
        async Task Post(string actor, string role, string path, object? body = null, int expected = 204) { using var r = await h.Send(actor, role, HttpMethod.Post, h.Path(path), body); await IncrementalHttpHarness.Status(r, expected); }
        async Task Measure(Guid id, string action, Func<MeasurementCommand, MeasurementCommand>? extra = null) { var state = await Measurements(); var c = new MeasurementCommand(Guid.NewGuid(), state.Revision, action, id); await Post("installer", "Installation", "measurements/commands", extra?.Invoke(c) ?? c); }
        async Task Complete(IEnumerable<MeasurementStructureView> rows) { foreach (var s in rows) { await Measure(s.Id, "RecordActual", c => c with { ActualWidth = s.Width, ActualHeight = s.Height, ActualSystemText = "Synthetic system", MeasurementType = "Agreed", ActualLocation = s.Location }); await Measure(s.Id, "RecordTechnical", c => c with { Technical = new("NotApplicable", null, "Outside", "NotApplicable", null, null, false, null) }); await Measure(s.Id, "RecordSketch", c => c with { Sketch = BrowserSketchFixture.Upload() }); await Measure(s.Id, "ResolveComparison", c => c with { Comparison = new("Comparable", "Synthetic agreed dimensions") }); await Measure(s.Id, "Measure", c => c with { Measured = true }); } }
        async Task<MeasurementDelivery> Submit(Guid[] ids) { var state = await Measurements(); using var r = await h.Send("installer", "Installation", HttpMethod.Post, h.Path("measurements/submissions"), new MeasurementSubmissionCommand(Guid.NewGuid(), state.Revision, ids, [])); await IncrementalHttpHarness.Status(r, 201); return (await r.Content.ReadFromJsonAsync<MeasurementDelivery>(IncrementalHttpHarness.Json))!; }
        async Task<byte[]> Report(Guid id) { using var r = await h.Send("installer", "Installation", HttpMethod.Get, h.Path($"measurements/submissions/{id}/report")); await IncrementalHttpHarness.Status(r, 200); Assert.Equal("application/pdf", r.Content.Headers.ContentType!.MediaType); return await r.Content.ReadAsByteArrayAsync(); }
        async Task<EngineeringCommandResult> Eng(string actor, EngineeringCommand c) { using var r = await h.Send(actor, "Engineering", HttpMethod.Post, h.Path("engineering/workspace/commands"), c); await IncrementalHttpHarness.Status(r, 200); return (await r.Content.ReadFromJsonAsync<EngineeringCommandResult>(IncrementalHttpHarness.Json))!; }
        async Task<CommercialOpeningResult> Cmd(Guid acta, CommercialOpeningCommand c, string actor = "advisor", string role = "CommercialAdvisor") { using var r = await h.Send(actor, role, HttpMethod.Post, h.Path($"incremental-opening-records/{acta}/commands"), c); await IncrementalHttpHarness.Status(r, 200); return (await r.Content.ReadFromJsonAsync<CommercialOpeningResult>(IncrementalHttpHarness.Json))!; }
        CommercialOpeningSelection Ref(CommercialOpeningRowView row) => new(row.Structure.Id, row.Revision, row.EvidenceVersion);
        CommercialOpeningCommand Command(string action, CommercialOpeningRoundView r) => new(Guid.NewGuid(), action, r.Revision, r.Id);
        async Task<Guid> Upload(Guid acta, CommercialOpeningRoundView r, CommercialOpeningSelection[] rows, byte[] bytes, CommercialOpeningReviewView? review = null) { using var form = new MultipartFormDataContent(); form.Add(JsonContent.Create(new CommercialOpeningUpload(Guid.NewGuid(), review?.Revision ?? r.Revision, review == null ? "SIGNED" : "REVISED", review?.Id, rows), options: IncrementalHttpHarness.Json), "manifest"); form.Add(new ByteArrayContent(bytes), "file", "synthetic.pdf"); await Post(review == null ? "advisor" : "worker", review == null ? "CommercialAdvisor" : "Engineering", $"incremental-opening-records/{acta}/rounds/{r.Id}/documents", form); return (await Commercial()).Actas.Single(a => a.Id == acta).Documents.Last(d => d.Kind == (review == null ? "SIGNED" : "REVISED")).Document.Id; }
        async Task<CommercialOpeningActaView> Acta(Guid id) => (await Commercial()).Actas.Single(a => a.Id == id);
        async Task<Guid> CreateActa(Guid[] ids, byte[] pdf)
        {
            var state = await Engineering(); var refs = state.Structures.Where(r => ids.Contains(r.Structure.Id)).Select(r => new EngineeringReference(r.Structure.Id, r.Origin!.SubmissionId, r.Origin.EvidenceVersion)).ToArray(); await Eng("engineer", new(Guid.NewGuid(), state.Workspace!.Revision, "CreatePackage", null, "worker", refs, null));
            foreach (var id in ids)
            {
                var row = (await Engineering()).Structures.Single(r => r.Structure.Id == id);
                if (id == ids[0]) { var checks = await Task.WhenAll(h.Send("worker", "Engineering", HttpMethod.Put, h.Path($"engineering/structures/{id}/check"), new EngineeringCheck(Guid.NewGuid(), row.Revision, true)), h.Send("worker", "Engineering", HttpMethod.Put, h.Path($"engineering/structures/{id}/check"), new EngineeringCheck(Guid.NewGuid(), row.Revision, true))); Assert.Equal(new[] { 204, 409 }, checks.Select(x => (int)x.StatusCode).Order().ToArray()); foreach (var check in checks) check.Dispose(); continue; }
                using var checkedResponse = await h.Send("worker", "Engineering", HttpMethod.Put, h.Path($"engineering/structures/{id}/check"), new EngineeringCheck(Guid.NewGuid(), row.Revision, true)); await IncrementalHttpHarness.Status(checkedResponse, 204);
            }
            state = await Engineering(); var result = await Eng("worker", new(Guid.NewGuid(), state.Workspace!.Revision, "CreateActa", null, null, refs, null)); state = await Engineering(); var a = state.Workspace!.Actas.Single(a => a.Id == result.TargetId);
            using var form = new MultipartFormDataContent(); form.Add(JsonContent.Create(new { files = new[] { new { partName = "file-0", replacesDocumentId = (Guid?)null } } }), "manifest"); form.Add(new ByteArrayContent(pdf), "file-0", "synthetic-acta.pdf"); await Post("worker", "Engineering", $"engineering/opening-records/{a.Id}/documents?requestKey={Guid.NewGuid()}&expectedRevision={a.Revision}&scopeHash={a.ScopeHash}", form);
            a = (await Engineering()).Workspace!.Actas.Single(x => x.Id == a.Id); var confirm = new EngineeringCommand(Guid.NewGuid(), a.Revision, "ConfirmActa", a.Id, null, null, null); var confirms = await Task.WhenAll(Eng("worker", confirm), Eng("worker", confirm)); Assert.Equal(confirms[0], confirms[1]); return a.Id;
        }
        await Post("installer", "Installation", "measurements/initialize"); var initial = await Measurements(); Assert.Equal(10, initial.Structures.Count); var first = initial.Structures.Take(4).ToArray(); var remaining = initial.Structures.Skip(4).ToArray();
        await Complete(first); var tranche1 = await Submit(first.Select(s => s.Id).ToArray()); var pdf1 = await Report(tranche1.Id); Assert.Equal(2, Regex.Matches(Encoding.Latin1.GetString(pdf1), @"/Type /Page\b").Count); Assert.Equal(4, tranche1.StructureIds.Count);
        var afterFirst = await Measurements(); Assert.True(afterFirst.CanModify); Assert.Equal("InProgress", afterFirst.TaskStatus); Assert.Equal(6, afterFirst.Structures.Count(s => s.MeasuredAt == null));
        foreach (var s in first) await Post("installer", "Installation", "measurements/commands", new MeasurementCommand(Guid.NewGuid(), afterFirst.Revision, "Retire", s.Id), 409);
        var eng1 = await Engineering(); Assert.Equal(first.Select(s => s.Id), eng1.Structures.Select(r => r.Structure.Id)); Assert.All(eng1.Structures, r => { Assert.NotNull(r.Structure.SketchVersionId); Assert.NotNull(r.Structure.ImageCatalogItemId); });
        var actaA = await CreateActa(first.Select(s => s.Id).ToArray(), pdf1); var a = await Acta(actaA); var rA = a.Rounds.Single(); Assert.Equal(1, rA.Number); Assert.Null(rA.PresentedAt); Assert.Null(rA.ElapsedSeconds);
        h.Clock.Now = h.Clock.Now.AddMinutes(2); var present = Command("Present", rA); var presentations = await Task.WhenAll(Cmd(a.Id, present), Cmd(a.Id, present)); Assert.Equal(presentations[0], presentations[1]); a = await Acta(a.Id); rA = a.Rounds.Single();
        h.Clock.Now = h.Clock.Now.AddMinutes(3); var signedA = await Upload(a.Id, rA, rA.Structures.Take(2).Select(Ref).ToArray(), pdf1);
        var accept = Command("Accept", rA) with { Structures = rA.Structures.Take(2).Select(Ref).ToArray(), DocumentId = signedA, Attest = true };
        await Post("advisor", "CommercialAdvisor", $"incremental-opening-records/{a.Id}/commands", accept with { Attest = false }, 400);
        // Authenticated file reads preserve exact bytes; corrupt and missing storage block acceptance.
        await using (var db = h.Db()) { var document = await db.ProjectDocuments.SingleAsync(d => d.Id == signedA); await h.Files.DeleteAsync(document.StorageKey, default); await h.Files.SaveAsync(document.StorageKey, new byte[pdf1.Length], default); await Post("advisor", "CommercialAdvisor", $"incremental-opening-records/{a.Id}/commands", accept, 409); await h.Files.DeleteAsync(document.StorageKey, default); await Post("advisor", "CommercialAdvisor", $"incremental-opening-records/{a.Id}/commands", accept, 409); await h.Files.SaveAsync(document.StorageKey, pdf1, default); }
        var accepts = await Task.WhenAll(Cmd(a.Id, accept), Cmd(a.Id, accept)); Assert.Equal(accepts[0], accepts[1]);
        a = await Acta(a.Id); rA = a.Rounds.Single(); Assert.Equal(2, rA.Structures.Count(x => x.Approval == "Confirmed")); Assert.Single(a.Acceptances); Assert.Equal(180, rA.FirstResponseSeconds); Assert.Null(rA.ResolvedAt);
        var requested = Command("RequestChanges", rA) with { Structures = [Ref(rA.Structures[2]) with { Description = "Correct third structure" }], Observations = "Synthetic general observation" }; var requests = await Task.WhenAll(h.Send("advisor", "CommercialAdvisor", HttpMethod.Post, h.Path($"incremental-opening-records/{a.Id}/commands"), requested), h.Send("advisor", "CommercialAdvisor", HttpMethod.Post, h.Path($"incremental-opening-records/{a.Id}/commands"), requested with { RequestKey = Guid.NewGuid() })); Assert.Equal(new[] { 200, 409 }, requests.Select(x => (int)x.StatusCode).Order().ToArray()); foreach (var response in requests) response.Dispose(); a = await Acta(a.Id); Assert.Equal("AwaitingApproval", a.Rounds[0].Structures[3].Approval); Assert.Equal("UnderEngineeringReview", a.Rounds[0].Structures[2].Approval);
        await using var frozen = h.Db(); var beforeMembers = await frozen.Set<MeasurementSubmissionMember>().AsNoTracking().Where(x => x.SubmissionId == tranche1.Id).OrderBy(x => x.StructureId).Select(x => x.SnapshotCanonical).ToArrayAsync();
        await Complete(remaining); var tranche2 = await Submit(remaining.Select(s => s.Id).ToArray()); Assert.Equal(2, tranche2.Number); Assert.Equal(6, tranche2.StructureIds.Count); var pdf2 = await Report(tranche2.Id); Assert.Equal(2, Regex.Matches(Encoding.Latin1.GetString(pdf2), @"/Type /Page\b").Count); Assert.Equal(pdf1, await Report(tranche1.Id)); Assert.Equal(beforeMembers, await frozen.Set<MeasurementSubmissionMember>().AsNoTracking().Where(x => x.SubmissionId == tranche1.Id).OrderBy(x => x.StructureId).Select(x => x.SnapshotCanonical).ToArrayAsync());
        var eng2 = await Engineering(); Assert.Equal(10, eng2.Total); Assert.Equal(4, eng2.Completed); Assert.All(eng2.Structures.Take(4), x => Assert.True(x.Completed)); var actaB = await CreateActa(remaining.Take(2).Select(s => s.Id).ToArray(), pdf2);
        var b = await Acta(actaB); var rB = b.Rounds.Single(); Assert.NotEqual(rA.TaskId, rB.TaskId); await Cmd(b.Id, Command("Present", rB)); b = await Acta(b.Id); rB = b.Rounds.Single();
        var signedB = await Upload(b.Id, rB, [Ref(rB.Structures[0])], pdf2); await Cmd(b.Id, Command("Accept", rB) with { Structures = [Ref(rB.Structures[0])], DocumentId = signedB, Attest = true });
        a = await Acta(a.Id); rA = a.Rounds.Single(); var signedPending = await Upload(a.Id, rA, [Ref(rA.Structures[3])], pdf1); var acceptPending = Command("Accept", rA) with { Structures = [Ref(rA.Structures[3])], DocumentId = signedPending, Attest = true };
        a = await Acta(a.Id); rA = a.Rounds.Single(); var review = a.Reviews.Single(); var observed = review.Structures.Single(); await Task.WhenAll(Cmd(a.Id, acceptPending), Cmd(a.Id, Command("ReviewCheck", rA) with { ReviewId = review.Id, Structures = [new(observed.StructureId, observed.Revision, observed.EvidenceVersion)], Completed = true }, "worker", "Engineering"));
        a = await Acta(a.Id); review = a.Reviews.Single(); await Cmd(a.Id, Command("DeclareChanged", rA) with { ReviewId = review.Id, ExpectedRevision = review.Revision, Structures = [Ref(rA.Structures[2])] }, "worker", "Engineering");
        a = await Acta(a.Id); rA = a.Rounds.Single(); review = a.Reviews.Single(); var revised = await Upload(a.Id, rA, rA.Structures.Select(Ref).ToArray(), pdf2, review); a = await Acta(a.Id); review = a.Reviews.Single(); await Cmd(a.Id, Command("CloseReview", rA) with { ReviewId = review.Id, ExpectedRevision = review.Revision, DocumentId = revised }, "worker", "Engineering");
        a = await Acta(a.Id); rA = a.Rounds.Last(); Assert.Equal(2, rA.Number); Assert.Equal(3, rA.Structures.Count(x => x.Approval == "Confirmed")); Assert.Equal(2, rA.Structures[2].EvidenceVersion); Assert.Equal(1, rA.Structures[0].EvidenceVersion); await Cmd(a.Id, Command("Present", rA));
        await Post("advisor", "CommercialAdvisor", $"incremental-opening-records/{a.Id}/commands", Command("Accept", rA) with { Structures = [Ref(rA.Structures[2])], DocumentId = signedA, Attest = true }, 409);
        var correctedSigned = await Upload(a.Id, rA, [Ref(rA.Structures[2])], pdf2); await Cmd(a.Id, Command("Accept", rA) with { Structures = [Ref(rA.Structures[2])], DocumentId = correctedSigned, Attest = true });
        var final = await Commercial(); Assert.Equal(2, final.Actas.Count); Assert.Equal("Resolved", final.Actas.Single(x => x.Id == actaA).Rounds.Last().Status); Assert.Equal("Presented", final.Actas.Single(x => x.Id == actaB).Rounds.Single().Status); Assert.Equal("AwaitingApproval", final.Actas.Single(x => x.Id == actaB).Rounds.Single().Structures[1].Approval); Assert.Equal(4, final.Actas.Sum(x => x.Acceptances.Count));
        Assert.True((await Measurements()).CanModify); Assert.Equal("InProgress", (await Engineering()).TaskStatus);
        await using (var db = h.Db()) { var filings = await db.ProjectTasks.Where(t => t.ProjectId == h.ProjectId && t.Type == ProjectTaskType.FileOpeningRecord).ToArrayAsync(); Assert.Equal(4, filings.Length); Assert.All(filings, t => { Assert.Equal(ProjectTaskStatus.Pending, t.Status); Assert.Null(t.DeadlineAt); Assert.Null(t.StartedAt); }); Assert.Equal(5, await db.Set<OpeningAcceptanceMember>().CountAsync(x => x.ProjectId == h.ProjectId)); Assert.Equal(2, await db.Set<MeasurementSubmission>().CountAsync(x => x.ProjectId == h.ProjectId)); Assert.NotEmpty(await db.ProjectNotifications.Where(n => n.ProjectId == h.ProjectId).ToArrayAsync()); }
        // Removing configured membership invalidates even an otherwise idempotent retry.
        h.SetAdvisorMembership("other-advisor");
        await Post("advisor", "CommercialAdvisor", $"incremental-opening-records/{actaA}/commands", accept, 403);
        h.SetAdvisorMembership("advisor", "other-advisor");
        // Real HTTP security boundary: no session, wrong role, unassigned identity and cross-Acta document.
        await Post("", "", $"incremental-opening-records/{actaB}/commands", Command("Present", rB), 401);
        foreach (var pair in new[] { ("worker", "Engineering"), ("advisor", "Management"), ("other-advisor", "CommercialAdvisor") }) await Post(pair.Item1, pair.Item2, $"incremental-opening-records/{actaB}/commands", Command("Present", rB), 403);
        using (var denied = await h.Send("other-advisor", "CommercialAdvisor", HttpMethod.Get, h.Path($"incremental-opening-records/{actaA}/documents/{signedA}/download"))) await IncrementalHttpHarness.Status(denied, 403);
        using (var cross = await h.Send("advisor", "CommercialAdvisor", HttpMethod.Get, h.Path($"incremental-opening-records/{actaB}/documents/{signedA}/download"))) await IncrementalHttpHarness.Status(cross, 404);
        using (var read = await h.Send("advisor", "CommercialAdvisor", HttpMethod.Get, h.Path($"incremental-opening-records/{actaA}/documents/{signedA}/download"))) { await IncrementalHttpHarness.Status(read, 200); Assert.Equal(pdf1, await read.Content.ReadAsByteArrayAsync()); Assert.True(read.Headers.CacheControl!.NoStore); }
        if (Environment.GetEnvironmentVariable("SNG_E2E_ARTIFACTS") is { } output) { Directory.CreateDirectory(output); await File.WriteAllBytesAsync(Path.Combine(output, "tramo-01.pdf"), pdf1); await File.WriteAllBytesAsync(Path.Combine(output, "tramo-02.pdf"), pdf2); await File.WriteAllTextAsync(Path.Combine(output, "commercial-state.json"), JsonSerializer.Serialize(final, IncrementalHttpHarness.Json)); await File.WriteAllTextAsync(Path.Combine(output, "engineering-state.json"), JsonSerializer.Serialize(await Engineering(), IncrementalHttpHarness.Json)); await File.WriteAllTextAsync(Path.Combine(output, "measurement-state.json"), JsonSerializer.Serialize(await Measurements(), IncrementalHttpHarness.Json)); await File.WriteAllTextAsync(Path.Combine(output, "evidence.json"), JsonSerializer.Serialize(new { h.ProjectId, Tranche1 = tranche1.Id, Tranche2 = tranche2.Id, ActaA = actaA, ActaB = actaB, AcceptedStructures = 5, FilingTasks = 4, Pdf1Sha256 = Convert.ToHexString(SHA256.HashData(pdf1)), Pdf2Sha256 = Convert.ToHexString(SHA256.HashData(pdf2)), Transport = Environment.GetEnvironmentVariable("SNG_E2E_BFF_URL") is null ? "HTTP Backend + PostgreSQL" : "Next BFF + HTTP Backend + PostgreSQL" })); }
    }
}
